# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-21
# Pester tests: dir-tar recipe.

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')
}

AfterAll {
    Remove-TestWork
}

Describe 'dir-tar recipe' -Skip:(-not $IsLinux) {
    BeforeAll {
        # a fake registry-like store: two parts, the referencing one listed first
        $script:st = Join-Path $Work 'dt-store'
        $files = [ordered]@{
            'v2/repositories/app/_manifests/tags/1.0/current/link' = 'sha256:aa'
            'v2/repositories/app/_uploads/tmp1/data'               = 'partial upload'
            'v2/blobs/sha256/aa/aa/data'                           = 'manifest'
            'v2/blobs/sha256/bb/bb/data'                           = 'layer'
            'v2/blobs/sha256/cc/cc/data'                           = 'excluded by path'
        }
        foreach ($k in $files.Keys) {
            $p = Join-Path $st $k
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $p) | Out-Null
            Set-Content -LiteralPath $p -Value $files[$k]
        }
        $script:rel = $st.TrimStart('/')

        $script:newDt = {
            param($envHash, $outName)
            $rc = & (Get-Module BackupCommon) { [RecipeContext]::new() }   # class lives in the module scope
            $rc.Service = 'registry'
            $rc.OutDir = Join-Path $Work $outName
            $rc.Env = [pscustomobject]$envHash
            $rc.ConfiguredSteps = @('dump')
            & (Join-Path $TestsDir '../src/recipes/dir-tar.ps1') -Recipe $rc | Out-Null
            $rc
        }
    }

    It 'archives the dirs in the configured order, relative to /, minus the excludes' {
        Set-StrictMode -Version Latest   # as the engine runs steps
        # repositories (r) after blobs (b) alphabetically: listed first to prove the order
        $rc = & $newDt @{ DT_DIRS = "$st/v2/repositories;$st/v2/blobs/"; DT_EXCLUDES = "_uploads;$st/v2/blobs/sha256/cc" } 'dt-out1'
        & $rc.Steps['dump'] $rc
        $list = @(& tar -tf (Join-Path $rc.OutDir 'registry.tar'))

        $list[0] | Should -Be "$rel/v2/repositories/"
        $lastRepo = [array]::FindLastIndex([string[]]$list, [Predicate[string]] { param($x) $x.StartsWith("$rel/v2/repositories/") })
        $firstBlob = [array]::FindIndex([string[]]$list, [Predicate[string]] { param($x) $x.StartsWith("$rel/v2/blobs/") })
        $lastRepo | Should -BeLessThan $firstBlob
        $list | Should -Contain "$rel/v2/repositories/app/_manifests/tags/1.0/current/link"
        $list | Should -Contain "$rel/v2/blobs/sha256/bb/bb/data"
        ($list -join "`n") | Should -Not -Match '_uploads'                 # name pattern
        ($list -join "`n") | Should -Not -Match 'sha256/cc'                # absolute path
        ($list -join "`n") | Should -Not -Match '(?m)^/'                   # relative to /
    }

    It 'uses DT_ARCHIVE_NAME and stores numeric owners' {
        Set-StrictMode -Version Latest
        $rc = & $newDt @{ DT_DIRS = "$st/v2/blobs"; DT_ARCHIVE_NAME = 'blobs.tar' } 'dt-out2'
        & $rc.Steps['dump'] $rc
        $tar = Join-Path $rc.OutDir 'blobs.tar'
        (Test-Path -LiteralPath $tar) | Should -BeTrue
        $uid = (& id -u).Trim()
        (@(& tar --numeric-owner -tvf $tar)[0]) | Should -Match "^\S+ $uid/"
    }

    It 'validate flags unset, relative, missing, a file, overlap and the root' {
        Set-StrictMode -Version Latest
        $p = @(& (& $newDt @{} 'dt-v0').ValidateBlock (& $newDt @{} 'dt-v0'))
        $p -join "`n" | Should -Match 'DT_DIRS not set'

        $file = "$st/v2/blobs/sha256/bb/bb/data"
        $rc = & $newDt @{ DT_DIRS = "rel/dir;$st/nope;$file;$st/v2;$st/v2/blobs;/" } 'dt-v1'
        $p = (@(& $rc.ValidateBlock $rc)) -join "`n"
        $p | Should -Match 'not absolute: rel/dir'
        $p | Should -Match "missing or not a dir: $st/nope"
        $p | Should -Match 'missing or not a dir: .*/bb/data'
        $p | Should -Match "overlap: $st/v2, $st/v2/blobs"
        $p | Should -Match 'is the root: /'

        $rc = & $newDt @{ DT_DIRS = "$st/v2/repositories;$st/v2/blobs" } 'dt-v2'
        @(& $rc.ValidateBlock $rc).Count | Should -Be 0
    }

    It 'refuses to dump with an invalid DT_DIRS (nothing archived partly)' {
        Set-StrictMode -Version Latest
        $rc = & $newDt @{ DT_DIRS = "$st/v2/blobs;$st/nope" } 'dt-out3'
        { & $rc.Steps['dump'] $rc } | Should -Throw '*missing or not a dir*'
        (Test-Path -LiteralPath (Join-Path $rc.OutDir 'registry.tar')) | Should -BeFalse
    }

    Context 'tar exit codes (stub tar on PATH)' {
        BeforeAll {
            $script:stubDir = Join-Path $Work 'dt-tar-stub'
            New-Item -ItemType Directory -Force -Path $stubDir | Out-Null
            $script:savedPath = $env:PATH
        }
        AfterEach { $env:PATH = $savedPath }

        It 'exit 1 is one warning, exit 2 throws' {
            Set-StrictMode -Version Latest
            foreach ($code in 1, 2) {
                $p = Join-Path $stubDir 'tar'
                Set-Content -LiteralPath $p -NoNewline -Value "#!/bin/sh`nexit $code"
                & chmod '+x' $p
                $env:PATH = "${stubDir}:$savedPath"
                $rc = & $newDt @{ DT_DIRS = "$st/v2/blobs" } "dt-out-exit$code"
                if ($code -eq 1) {
                    $warn = @(& $rc.Steps['dump'] $rc 3>&1 | Where-Object { $_ -is [System.Management.Automation.WarningRecord] })
                    $warn.Count | Should -Be 1
                    "$($warn[0].Message)" | Should -Match 'changed while being read'
                }
                else {
                    { & $rc.Steps['dump'] $rc } | Should -Throw '*exit 2*'
                }
            }
        }
    }

    It 'publishes the tar through a real run' {
        $n = [guid]::NewGuid().ToString('n').Substring(0, 8)
        $root = Join-Path $Work "dt-lc-$n"
        $paths = @{ BaseDir = $TestsDir; EventsPath = (Join-Path $Work "dt-lc-$n.jsonl"); LockPath = ($root + '.lock'); SpoolRoot = $root }
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "registry": { "enabled": true, "script": "../src/recipes/dir-tar.ps1",
    "env": { "DT_DIRS": "__DIRS__" },
    "steps": [ { "name": "dump", "resources": [] } ] } } }
'@ -replace '__DIRS__', "$st/v2/repositories;$st/v2/blobs") | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path -LiteralPath (Join-Path $root 'ready/registry/registry.tar')) | Should -BeTrue
    }
}
